5. 
6. // Train the model at startup
7. var mlContext = new MLContext(seed: 42);
8. var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
9. var dataView = mlContext.Data.LoadFromTextFile<ChurnInput>(dataPath, hasHeader: true, separatorChar: ',');
10. 
11. // With larger datasets, use: mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2)
12. var pipeline = mlContext.Transforms.CustomMapping<ChurnInput, ChurnLabel>(
13.         (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
14.         contractName: "ChurnLabelMapping")
15.     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(ChurnInput.Region)))
16.     .Append(mlContext.Transforms.NormalizeMinMax(nameof(ChurnInput.Age)))
17.     .Append(mlContext.Transforms.NormalizeMinMax(nameof(ChurnInput.Income)))
18.     .Append(mlContext.Transforms.NormalizeMinMax(nameof(ChurnInput.PurchaseHistory)))
19.     .Append(mlContext.Transforms.Concatenate("Features",
20.         nameof(ChurnInput.Age), nameof(ChurnInput.Income), "RegionEncoded", nameof(ChurnInput.PurchaseHistory)))
21.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());
22. 
23. var model = pipeline.Fit(dataView);
24. 
25. var predictions = model.Transform(dataView);
26. var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
27. Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
28. 
29. builder.Services.AddSingleton(mlContext);
30. builder.Services.AddSingleton(model);
31. 
32. var app = builder.Build();
33. 
